Exemple de code Arduino avancé

#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
#define CLK 4
#define DT 3
#define SW 2

int counter = 0;
int currentStateCLK;
int lastStateCLK;
String currentDir = "";

void setup() {
  lcd.begin();
  lcd.backlight();
  Serial.begin(9600);
  pinMode(CLK, INPUT);
  pinMode(DT, INPUT);
  pinMode(SW, INPUT_PULLUP);
  lastStateCLK = digitalRead(CLK);
}

void loop() {
  currentStateCLK = digitalRead(CLK);
  if (currentStateCLK != lastStateCLK) {
    if (digitalRead(DT) != currentStateCLK) {
      counter--;
      currentDir = "CCW";
    } else {
      counter++;
      currentDir = "CW";
    }
    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print("Pos: ");
    lcd.print(counter);
    lcd.setCursor(0, 1);
    lcd.print("Dir: ");
    lcd.print(currentDir);
  }
  lastStateCLK = currentStateCLK;

  if (digitalRead(SW) == LOW) {
    Serial.println("Button Pressed");
  } else {
    Serial.println("Button Released");
  }
  delay(50);
}

